package ar.com.liftmanager.controller;
import ar.com.liftmanager.dto.ApiDtos.*;import ar.com.liftmanager.service.*;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api") public class ElevatorController {private final ElevatorService service;public ElevatorController(ElevatorService s){service=s;}@GetMapping("/elevators") public List<ElevatorView> list(){return service.list();}@PostMapping("/buildings/{buildingId}/elevators") public ElevatorView create(@PathVariable Long buildingId,@Valid @RequestBody ElevatorRequest r){return service.create(buildingId,r);}@PatchMapping("/elevators/{id}/status") public ElevatorView status(@PathVariable Long id,@Valid @RequestBody ElevatorStatusRequest r){return service.updateStatus(id,r.status());}@PostMapping("/elevators/{id}/contracts") public ContractView contract(@PathVariable Long id,@Valid @RequestBody ContractRequest r){return service.createContract(id,r);}}
